IOSink _callbacksSink() => _BufSink(StringBuffer());

class _BufSink implements IOSink {
  final StringBuffer _buf;
  _BufSink(this._buf);
  @override
  void write(Object? obj) => _buf.write(obj);
  @override
  void writeln([Object? obj = '']) => _buf.writeln(obj);
  @override
  void writeAll(Iterable<Object?> objects, [String separator = '']) =>
      _buf.writeAll(objects, separator);
  @override
  void writeCharCode(int charCode) => _buf.writeCharCode(charCode);
  @override
  Future<void> flush() async {}
  @override
  Future<void> close() async {}
  @override
  Future<void> get done async {}
  @override
  void add(List<int> data) {}
  @override
  void addError(Object error, [StackTrace? stackTrace]) {}
  @override
  Future<void> addStream(Stream<List<int>> stream) async {}
  @override
  Encoding get encoding => utf8;
  @override
  set encoding(Encoding value) {}
}

void main() {
  Map<String, String> goldens() {
    final g = <String, String>{};
    for (final line in File(
      'test/cli/fa_tui_viewport_fold_golden.txt',
    ).readAsLinesSync()) {
      if (line.isEmpty || line.startsWith('#')) continue;
      final split = line.split(' ');
      g[split[0]] = split[1];
    }
    return g;
  }

  String render(FaTuiModel model) {
    final buf = StringBuffer();
    CellRenderer(
      output: _BufSink(buf),
      logSink: null,
      defaultAltScreen: false,
      defaultHideCursor: false,
    ).render(model.view());
    return base64Encode(utf8.encode(buf.toString()));
  }

  FaTuiModel build() => FaTuiModel(
    callbacks: FaTuiCallbacks(
      onSubmit: (_, {images = const []}) async {},
      onModelSelected: (_) async {},
      buildSlashMenu: (_) => const [],
      buildModelMenu: (_, _) => const [],
      statusLine: () => '/work · 0tok · turn 0 · test-model',
      prompt: 'fa> ',
    ),
    isExited: () => false,
    termWidth: 80,
    termHeight: 24,
    mouseCapture: true,
  );

  test('F1/F3 goldens match pristine bytes', () {
    final g = goldens();
    var short = build();
    short = short.update(OutputMsg('hello world', newline: true)).$1
        as FaTuiModel;
    expect(render(short), g['F1'], reason: 'F1 pristine');

    var long = build();
    for (var i = 0; i < 60; i++) {
      long = long.update(OutputMsg('stream line $i', newline: true)).$1
          as FaTuiModel;
    }
    var up = long;
    up = up.update(KeyPressMsg(const TeaKey(code: KeyCode.pageUp))).$1
        as FaTuiModel;
    up = up.update(KeyPressMsg(const TeaKey(code: KeyCode.pageUp))).$1
        as FaTuiModel;
    expect(render(up), g['F3'], reason: 'F3 pristine');
  });
}
