/// per-frame `List<String>` allocation. Used by the view assembly for cursor
/// row math on every rendered frame.
int _lineCount(String s) {
  var n = 1;
  var start = 0;
  for (;;) {
    final i = s.indexOf('\n', start);
    if (i < 0) break;
    n++;
    start = i + 1;
  }
  return n;
}

