    StringBuffer b,
    int height,
    List<String> wrapped,
    int offset,
  ) {
    for (var i = 0; i < height; i++) {
      final row = offset + i;
      b.writeln(row < wrapped.length ? wrapped[row] : '');
    }
    return height;
  }

