  /// [_menuWindow] and the frame-height budget both pay THIS number, so
  /// a window that fits the budget here cannot overrun the glass.
  int _menuLines(int start, int end) {
    var lines = 1 + (end - start); // title + items
    lines += _groupHeadersIn(start, end); // section headers
    if (start > 0) lines++; // '↑ more'
    if (end < menuItems.length) lines++; // '↓ more'
    if (_modelPickerFamilyOpen) lines++; // footer hint
    return lines;
  }

  /// Group-header rows the visible window renders (one per group change,
  /// issue #275) — the height math and the renderer must agree.
  int _groupHeadersIn(int start, int end) {
    var count = 0;
    var last = '';
    for (var i = start; i < end; i++) {
      final group = menuItems[i].group;
      if (group.isNotEmpty && group != last) count++;
      last = group;
    }
    return count;
  }

  /// Applies a user scroll: moves the offset (clamped) and re-evaluates the
  /// follow latch — scrolling up detaches, landing back on the exact bottom
  /// re-attaches.
  FaTuiModel _scrolledTo(int offset) {
    final wrapped = _wrappedLines();
    final next = offset.clamp(0, _scrollTopMax(wrapped));
    return copyWith(
      scrollOffset: next,
      followTail: next >= _scrollBottom(wrapped),
    );
  }

  /// The current turn's first wrapped row (issue #827). -1 (nothing
  /// submitted yet) and out-of-range (the transcript head-trim dropped the
  /// echo — the index goes stale by the cut count) both return 0, riding
  /// the global bottom exactly like the pre-#827 follow.
  int _turnStartRow() {
    if (turnStartLine < 0) return 0;
    _wrappedLines(); // refresh the shared wrap cache when stale
    final starts = _wrapCache.lineStartRows;
    if (turnStartLine >= starts.length) return 0;
    return starts[turnStartLine];
