+      model = _send(model, KeyPressMsg(const TeaKey(code: KeyCode.pageUp)));
+      var top = _rowsOf(model);
+      expect(model.scrollOffset, 1, reason: '35 - 19 vh, clamped');
+      expect(_hintN(top), isNull, reason: 'detached: no hint at the top');
