+      model = model.copyWith(inputText: turnOne);
+      var result = model.update(
+        KeyPressMsg(const TeaKey(code: KeyCode.enter)),
+      );
+      model = result.$1 as FaTuiModel;
+      await result.$2?.call();
+      model = _send(model, const BusyMsg(true, source: 'run'));
