      if (includePending && inputText.trim().isNotEmpty) inputText.trim(),
      // Steering rows interrupt first; follow-ups keep queue order.
      ...[for (final m in queue.where((m) => m.steer)) m.text],
      ...[for (final m in queue.where((m) => !m.steer)) m.text],
    ];
    if (messages.isEmpty) return (this, null);
