final class _WrapCache {
  /// The [FaTuiModel.outputLines] instance the pass ran on.
  List<String>? source;
  int width = -1;
  List<String> rows = const [];

  /// `lineStartRows[i]` = first wrapped row of raw line `i`; the final entry
