+        outputLines: [for (var i = 0; i < 10; i++) '$wide $i'],
+        turnStartLine: 5,
+      );
+      final rows = _rowsOf(model);
+      expect(_hintN(rows), 10, reason: 'N counts wrapped rows');
+    });
+
