+      model = _send(model, KeyPressMsg(const TeaKey(code: KeyCode.pageDown)));
+      expect(model.followTail, isTrue);
+      expect(_hintN(_rowsOf(model)), 21, reason: 're-anchored at the fold');
+      expect(_hasPercent(_rowsOf(model)), isFalse);
+    });
+  });
