+      frames.add(_rowsOf(model));
+      model = _send(model, const BusyMsg(true, source: 'run'));
+      for (var i = 0; i < 30; i++) {
+        model = _send(model, OutputMsg('beta answer $i', newline: true));
+        frames.add(_rowsOf(model));
+      }
+      model = _send(model, const BusyMsg(false));
+      frames.add(_rowsOf(model));
